import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.Bqa2y7hU.js";const b=JSON.parse('{"title":"内置插件一览","description":"随框架提供的常用插件：群管、消息发送、自定义 API、关键词回复、入群欢迎等，各自能做什么、需不需要平台权限。","frontmatter":{"title":"内置插件一览","description":"随框架提供的常用插件：群管、消息发送、自定义 API、关键词回复、入群欢迎等，各自能做什么、需不需要平台权限。"},"headers":[],"relativePath":"console/builtin-plugins.md","filePath":"console/builtin-plugins.md","lastUpdated":1789270955000}'),d={name:"console/builtin-plugins.md"};function l(i,t,n,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="内置插件一览" tabindex="-1">内置插件一览 <a class="header-anchor" href="#内置插件一览" aria-label="Permalink to &quot;内置插件一览&quot;">​</a></h1><p>这些插件随框架提供，在控制台「插件市场」里可以直接装到你的机器人上。每一条都标了<strong>是否需要平台额外开权限</strong>——需要开权限的功能，没开通时的表现是&quot;操作失败&quot;，而不是静默无效。</p><div class="tip custom-block"><p class="custom-block-title">以市场为准</p><p>插件会持续增加和更新，<strong>本页只是导读</strong>；某个插件是否可用、当前版本、需要什么权限，以「插件市场」里实际列出的为准。</p></div><h2 id="社群管理" tabindex="-1">社群管理 <a class="header-anchor" href="#社群管理" aria-label="Permalink to &quot;社群管理&quot;">​</a></h2><h3 id="群管" tabindex="-1">群管 <a class="header-anchor" href="#群管" aria-label="Permalink to &quot;群管&quot;">​</a></h3><p>功能最全的一个，装到群管类机器人上基本够用：</p><table tabindex="0"><thead><tr><th>模块</th><th>能做什么</th></tr></thead><tbody><tr><td>内容拦截</td><td>违禁词（全群词库 + 分群词库）、链接、卡片/小程序、转发消息，命中后撤回 / 禁言 / 踢出可配</td></tr><tr><td>刷屏检测</td><td>按时间窗口与条数阈值判定，同样可配处置方式</td></tr><tr><td>成员处置</td><td>禁言、解禁、踢出（可同时拉黑）、针对某人自动撤回其消息</td></tr><tr><td>入群管理</td><td>入群验证（答题）、入群审批（手动 / 自动通过 / 自动拒绝 / 自动拉黑）、申请播报与一键审批</td></tr><tr><td>审计统计</td><td>所有处置动作留痕，可在插件面板里查</td></tr></tbody></table><ul><li><strong>有插件面板</strong>：词库、名单、功能开关、入群策略、回复模板、审计日志都在网页上配。</li><li><strong>按钮与 Markdown</strong>：QQ 官方平台下，入群审批播报会带可点击的按钮；其它平台用文字指令（如回复「同意 1」）。</li><li><strong>需要平台权限</strong>：禁言、踢人、查群成员、入群审批这些依赖平台接口，机器人还需是群管理员。见 <a href="/RuaBot.Doc/reference/capabilities">平台能力码</a>。</li></ul><h3 id="违禁词" tabindex="-1">违禁词 <a class="header-anchor" href="#违禁词" aria-label="Permalink to &quot;违禁词&quot;">​</a></h3><p>轻量版内容拦截：命中违禁词自动撤回，可选自动禁言，支持全局词库与分群词库。不需要面板，词库用群内指令维护。</p><h3 id="针对撤回" tabindex="-1">针对撤回 <a class="header-anchor" href="#针对撤回" aria-label="Permalink to &quot;针对撤回&quot;">​</a></h3><p>把指定成员加入「针对名单」，之后他在群里发的消息会被自动撤回。适合处理屡教不改的成员。</p><h3 id="入群欢迎" tabindex="-1">入群欢迎 <a class="header-anchor" href="#入群欢迎" aria-label="Permalink to &quot;入群欢迎&quot;">​</a></h3><p>群成员进群时发送欢迎语，支持黑白名单、每日次数上限与文案模板。</p><h2 id="消息与互动" tabindex="-1">消息与互动 <a class="header-anchor" href="#消息与互动" aria-label="Permalink to &quot;消息与互动&quot;">​</a></h2><h3 id="消息发送" tabindex="-1">消息发送 <a class="header-anchor" href="#消息发送" aria-label="Permalink to &quot;消息发送&quot;">​</a></h3><p><strong>网页直接给群发消息</strong>的控制台：左侧群列表、右侧聊天窗口，不用加插件、不用写指令。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>群列表</td><td>机器人收到过消息的群会自动出现在列表里，不需要手工配置</td></tr><tr><td>聊天窗口</td><td>显示该群最近的消息，<strong>收到和发出的都显示</strong>；从这里发出的消息会立刻出现在气泡流里</td></tr><tr><td>被动消息</td><td>用该群<strong>近 5 分钟</strong>内的消息作为回复凭证发送，不占用主动消息配额</td></tr><tr><td>主动消息</td><td>不需要回复凭证，但<strong>需要平台授权</strong>；没权限时面板会直接拒绝并提示改用被动消息</td></tr><tr><td>消息类型</td><td>文本、Markdown、图片（填图片链接）、图文混合</td></tr></tbody></table><p>几个使用要点：</p><ul><li><strong>Markdown 只在 QQ 官方平台渲染</strong>，其它平台会按纯文本发出（面板上有提示）。</li><li>图片只支持 <strong>URL</strong>，不是上传文件；把图片链接填进去即可。</li><li>「被动消息」为什么要求近 5 分钟：平台对引用原消息的被动回复豁免主动频控，超过 5 分钟凭证就失效了。这时改用「主动消息」。</li><li>面板显示的聊天记录会<strong>保留</strong>：每个群最近 50 条落库，服务重启后仍然能看到（更早的按条数自动滚动淘汰）。</li></ul><h3 id="自定义-api" tabindex="-1">自定义 API <a class="header-anchor" href="#自定义-api" aria-label="Permalink to &quot;自定义 API&quot;">​</a></h3><p>不用写代码，把「一段指令」接到「任意外部 HTTP 接口」上，并把返回结果按模板变成文本或图片回发。支持多步链式调用（前一个接口的结果喂给后一个）、变量替换与条件分支。<strong>有插件面板</strong>，配置在网页里完成。</p><h3 id="关键词回复" tabindex="-1">关键词回复 <a class="header-anchor" href="#关键词回复" aria-label="Permalink to &quot;关键词回复&quot;">​</a></h3><p>最简单的自动回复：群里出现某个关键词就回一段固定文本。<strong>有插件面板</strong>。</p><h3 id="多平台点歌" tabindex="-1">多平台点歌 <a class="header-anchor" href="#多平台点歌" aria-label="Permalink to &quot;多平台点歌&quot;">​</a></h3><p>支持网易云、QQ 音乐、汽水、酷我四个平台：搜索 → 按钮选歌 → 歌词 / 卡片 / 下载链接。</p><h3 id="群禁言" tabindex="-1">群禁言 <a class="header-anchor" href="#群禁言" aria-label="Permalink to &quot;群禁言&quot;">​</a></h3><p>独立的小工具：群内发「禁言 @某人 分钟」或「解禁 @某人」。功能和群管插件里的禁言重叠，二选一即可。</p><h2 id="群信息与工具" tabindex="-1">群信息与工具 <a class="header-anchor" href="#群信息与工具" aria-label="Permalink to &quot;群信息与工具&quot;">​</a></h2><h3 id="群状态-群信息" tabindex="-1">群状态 / 群信息 <a class="header-anchor" href="#群状态-群信息" aria-label="Permalink to &quot;群状态 / 群信息&quot;">​</a></h3><p>查询群的名称、成员数、机器人在群里的角色、是否可主动推送消息、入群时间等信息。<strong>排错时很有用</strong>：怀疑权限问题时，先看一眼机器人当前的群内身份与授权状态。</p><h3 id="我的-id" tabindex="-1">我的 ID <a class="header-anchor" href="#我的-id" aria-label="Permalink to &quot;我的 ID&quot;">​</a></h3><p>回复发送者自己的标识（群里会附带群标识）。做接口联调、填「针对名单」时取标识用得上。</p><h3 id="全量申请" tabindex="-1">全量申请 <a class="header-anchor" href="#全量申请" aria-label="Permalink to &quot;全量申请&quot;">​</a></h3><p>生成「群全量消息授权」的深链，群主在 QQ 里点开即可授权。</p><div class="warning custom-block"><p class="custom-block-title">不授权会怎样</p><p>QQ 官方平台默认只把 <strong>@ 机器人</strong>的消息推给它。没做全量授权时，群管、关键词回复这类需要看全部消息的插件都不会触发。</p></div><h3 id="速度测试" tabindex="-1">速度测试 <a class="header-anchor" href="#速度测试" aria-label="Permalink to &quot;速度测试&quot;">​</a></h3><p>回复框架收到消息到发出回复的耗时，用来判断&quot;慢&quot;是慢在网络还是慢在插件。</p><h2 id="开发者示例" tabindex="-1">开发者示例 <a class="header-anchor" href="#开发者示例" aria-label="Permalink to &quot;开发者示例&quot;">​</a></h2><p>下面几个主要是给插件开发者看的参考实现，普通用户可以忽略：</p><table tabindex="0"><thead><tr><th>插件</th><th>用途</th></tr></thead><tbody><tr><td>回声</td><td>最小示例：被 @ 或私聊时原样回显，20 行代码</td></tr><tr><td>面板演示</td><td>演示插件自带 Web 面板怎么写（配置读写 + 动态接口）</td></tr><tr><td>能力探针</td><td>群内发 <code>/cap &lt;能力码&gt;</code> 直接调用平台能力并回显原始结果，调接口时非常好用</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/plugins">插件市场与安装</a>：怎么把插件装到机器人上</li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a>：机器人详情页的五个 Tab</li><li><a href="/RuaBot.Doc/faq">群管怎么用</a>：常见问题与排查</li></ul>',43)])])}const p=a(d,[["render",l]]);export{b as __pageData,p as default};
